/// Who owns a body's position, and the ONLY way to make something immovable. Rest is not immobility: rest is a solver optimisation that a heavy enough touch undoes, so a structure held up by rest collapses the moment something walks on it. Choose authority deliberately; do not rely on stillness.
enum class SolverAuthority {
    /// Physics owns it. Gravity pulls it, contacts push it, impulses move it. The default, and right for anything loose, alive, or meant to be knocked about.
    DYNAMIC,
    /// An external writer owns this body's position RIGHT NOW: animation, locomotion, a scripted driver. Physics will not move it while that lasts, and it still collides, so things land on it.
    /// It is a TRANSIENT AUTHORITY, not a label. Whoever sets it owns releasing it: a body left KINEMATIC after its driver stops can never fall, tip or ragdoll again. Driving complex animation through physics is the thing this escape hatch exists to avoid - nothing else.
    /// NOT for scenery. Terrain, floors and worlds are not immovable by declaration (INV-1: the turtle boundary is the only intrinsically immovable thing). They rest on the turtle, on anchored bonds, or on the modelled EFFECT of the mass we choose not to simulate - which is also where gravity comes from. A body that should float escapes the field; it is not nailed to the air.
    KINEMATIC
};

/// Convert SolverAuthority to its string representation.
inline const char* to_string(SolverAuthority value) {
    switch (value) {
        case SolverAuthority::DYNAMIC: return "DYNAMIC";
        case SolverAuthority::KINEMATIC: return "KINEMATIC";
    }
    return "unknown";
}

/// Parse a string into SolverAuthority. Returns false if the string is not a valid value.
inline bool from_string(const char* str, SolverAuthority& out) {
    if (std::strcmp(str, "DYNAMIC") == 0) { out = SolverAuthority::DYNAMIC; return true; }
    if (std::strcmp(str, "KINEMATIC") == 0) { out = SolverAuthority::KINEMATIC; return true; }
    return false;
}

/// Relation types between game world entities.
enum class WorldRelationType {
    /// Composition (humanoid has_part torso)
    HAS_PART,
    /// Spatial subdivision (arm has_regional_part forearm)
    HAS_REGIONAL_PART,
    /// Physics constraint link
    HAS_CONSTRAINT,
    /// Spatial containment (chest contains item)
    CONTAINS,
    /// Physical support (floor supports entity)
    SUPPORTS,
    /// Light source reaches entity
    ILLUMINATES,
    /// Fire spread between entities
    BURNS,
    /// Agent perceives target entity
    PERCEIVES,
    /// System entity manages another entity
    MANAGES,
    /// Direct bond between two bodies - the engine's cement. The bond is a physical constraint at bond_strength; strong bonds make many particles behave as one rigid body, weak ones give under load. Use it to fix things in place relative to each other rather than to the world.
    BONDED_TO,
    /// A narrower thing refines a broader one: the specialization points at what it specializes (Slug Rifle SPECIALIZES Gun Combat in a skill cascade). Generic taxonomy vocabulary, first used by the rulebook module's skill cascades.
    SPECIALIZES
};

